}
const C = pal();

// ---- banks (drifting shoals) ----
const nB = Math.round(P.banks + P.density * 2);
if (S.seed !== P.seed || S.nB !== nB) {
  S.seed = P.seed; S.nB = nB; S.B = [];
  for (let b = 0; b < nB; b++) S.B.push({ x: 0.15 + fr(b * 3 + 1) * 0.7, y: 0.15 + fr(b * 3 + 2) * 0.7, r: 0.08 + fr(b * 3 + 3) * 0.16, ph: fr(b * 7) * TAU, wob: 0.5 + fr(b * 5) * 0.5 });
}
const B = S.B;

background(C.deep[0], C.deep[1], C.deep[2]);
// deep sea faint texture band gradient
noStroke();
for (let r = 0; r < 4; r++) { fill(C.deep[0], C.deep[1], C.deep[2] * (1 + r * 0.06), 30); rect(0, height * r / 4, width, height / 4); }

