const nLev = 5 + Math.round(P.energy * 3);
strokeJoin(ROUND);

// draw each bank as nested isobaths, deepest first
for (let b = 0; b < nB; b++) {
  const bk = B[b];
  const bx = (bk.x + Math.sin(K.t * 0.05 + bk.ph) * 0.02) * width;
  const by = (bk.y + Math.cos(K.t * 0.043 + bk.ph * 1.3) * 0.02) * height;
