for (let k = 0; k < 32; k++) { const th = k / 32 * TAU + roseSpin; const long = k % 8 === 0; const short = k % 4 === 0; strokeWeight(long ? 1.3 : short ? 0.9 : 0.5); stroke(C.rose[0], C.rose[1], C.rose[2], long ? 60 : 30); line(0, 0, Math.cos(th) * rr * (long ? 1 : short ? 0.7 : 0.5), Math.sin(th) * rr * (long ? 1 : short ? 0.7 : 0.5)); }
noStroke(); fill(C.rose[0], C.rose[1], C.rose[2], 80); textAlign(CENTER, CENTER); textSize(rr * 0.11);
text('N', Math.cos(-Math.PI / 2 + roseSpin) * rr * 1.12, Math.sin(-Math.PI / 2 + roseSpin) * rr * 1.12);
